@spec library_spec  src=tests/specs/library_spec.lua  loc=268  cases=17
@exercises configManager (h.cm)
@surface   cm:getAt, cm:set, cm:defaultFor
@harness   mk

# Intent
  Pin-tests for library.lua: the shared project/library tier module. The
  factory catalogue (cm:defaultFor) is a seed source, not a resolution tier --
  seedIfEmpty stocks an empty library, reloadPlan/importFactory re-import it.
  Instantiated directly over a harness cm (no in-module production caller).
  One case per verb, plus the synthetic floor's exemptions.

# Helpers
  @fn mkLib(h)  @ 10-15

# Cases
  @case 'names splits project and library, dropping the synthetic floor'  [harness]  @ 19-30
  @case 'getAt reads the tier it is told, neither copy shadowing the other'  [harness]  @ 33-44
  @case 'localize copies a resolvable entry to project and is idempotent'  [harness]  @ 47-58
  @case 'localize skips synthetic names'  [harness]  @ 61-67
  @case 'forkToProject localizes then returns the project copy'  [harness]  @ 70-77
  @case 'save authors into project, leaving a same-named library copy standing'  [harness]  @ 80-93
  @case 'publish copies the project entry to the library tier'  [harness]  @ 97-105
  @case 'publish no-ops without a project copy'  [harness]  @ 108-114
  @case 'publishOverwrites is true only for a divergent library copy'  [harness]  @ 117-134
  @case 'revert overwrites the project copy from its library source'  [harness]  @ 137-147
  @case 'revert no-ops without a library source'  [harness]  @ 150-159
  @case 'modified: false pristine, true divergent, false for a source-less entry'  [harness]  @ 162-179
  @case 'tidy drops pristine unreferenced entries, keeps inUse and divergent ones'  [harness]  @ 182-205
  @case 'delete removes from the named tier and refuses synthetic names'  [harness]  @ 208-221
  @case 'seedIfEmpty stocks an empty library from the factory catalogue, once'  [harness]  @ 224-238
  @case 'reloadPlan splits absent factory names from divergent library copies'  [harness]  @ 241-254
  @case 'importFactory copies one entry into the library, refusing synthetic'  [harness]  @ 257-266

